package main

import (
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

// testPCAP is the shared test pcap generated by gen_test_pcap.py
var testPCAP string

func init() {
	// Resolve testdata/test.pcap relative to the epan module root
	wd, _ := os.Getwd()
	// Try a few locations
	candidates := []string{
		filepath.Join(wd, "testdata", "test.pcap"),
		filepath.Join(wd, "..", "testdata", "test.pcap"),
		filepath.Join(wd, "..", "..", "testdata", "test.pcap"),
	}
	for _, c := range candidates {
		if _, err := os.Stat(c); err == nil {
			testPCAP = c
			break
		}
	}
}

func runEpanCLI(args ...string) (string, error) {
	epanBin := os.Getenv("EPAN_TEST_BIN")
	if epanBin == "" {
		epanBin = "/tmp/epan"
	}
	cmd := exec.Command(epanBin, args...)
	cmd.Stderr = nil
	out, err := cmd.Output()
	return strings.TrimSpace(string(out)), err
}

func runEpanCLIJSON(args ...string) (map[string]any, error) {
	out, err := runEpanCLI(args...)
	if err != nil {
		return nil, fmt.Errorf("epan %s: %w\noutput: %s", strings.Join(args, " "), err, out)
	}
	var result map[string]any
	if err := json.Unmarshal([]byte(out), &result); err != nil {
		return nil, fmt.Errorf("parse JSON: %w\noutput: %s", err, out)
	}
	return result, nil
}

func TestIntegration_TriageComponents(t *testing.T) {
	if testPCAP == "" {
		t.Skip("test pcap not found, run gen_test_pcap.py first")
	}

	// 1. Frame count
	t.Run("frame_count", func(t *testing.T) {
		result, err := runEpanCLIJSON("frames", "count", "--file", testPCAP)
		if err != nil {
			t.Fatal(err)
		}
		count, ok := result["count"].(float64)
		if !ok {
			t.Fatalf("count not found or wrong type: %v", result)
		}
		if count != 71 {
			t.Errorf("frame count = %v, want 71", count)
		}
		t.Logf("frame count: %v", count)
	})

	// 2. Frame count with filter
	t.Run("frame_count_filtered", func(t *testing.T) {
		result, err := runEpanCLIJSON("frames", "count", "--file", testPCAP, "--filter", "tcp")
		if err != nil {
			t.Fatal(err)
		}
		count, ok := result["count"].(float64)
		if !ok {
			t.Fatalf("count not found: %v", result)
		}
		if count <= 0 {
			t.Errorf("TCP frame count should be > 0, got %v", count)
		}
		t.Logf("TCP frame count: %v", count)
	})

	// 3. Streams
	t.Run("streams", func(t *testing.T) {
		result, err := runEpanCLIJSON("streams", "list", "--file", testPCAP)
		if err != nil {
			t.Fatal(err)
		}
		list, ok := result["list"].([]any)
		if !ok {
			t.Fatalf("streams list not found or wrong type: %v", result)
		}
		if len(list) == 0 {
			t.Error("expected at least 1 stream")
		}
		t.Logf("streams: %d", len(list))
		for i, s := range list {
			t.Logf("  stream %d: %v", i, s)
		}
	})

	// 4. Expert findings
	t.Run("expert", func(t *testing.T) {
		result, err := runEpanCLIJSON("expert", "list", "--file", testPCAP)
		if err != nil {
			t.Fatal(err)
		}
		// expert may return empty list for synthetic pcap, which is fine
		if _, ok := result["list"]; !ok {
			t.Error("expert output missing 'list' field")
		}
		t.Logf("expert: %v", result["list"])
	})

	// 5. Stats
	t.Run("stats", func(t *testing.T) {
		result, err := runEpanCLIJSON("stats", "--file", testPCAP)
		if err != nil {
			t.Fatal(err)
		}
		if _, ok := result["protocols"]; !ok {
			t.Error("stats missing 'protocols' field")
		}
		t.Logf("stats protocols: %v", result["protocols"])
	})

	// 6. Conversations
	t.Run("conversations", func(t *testing.T) {
		result, err := runEpanCLIJSON("traffic", "conversations", "list", "--file", testPCAP)
		if err != nil {
			t.Fatal(err)
		}
		list, ok := result["list"].([]any)
		if !ok {
			t.Fatalf("conversations list not found: %v", result)
		}
		if len(list) == 0 {
			t.Error("expected at least 1 conversation")
		}
		t.Logf("conversations: %d", len(list))
	})
}

func TestIntegration_Frames(t *testing.T) {
	if testPCAP == "" {
		t.Skip("test pcap not found, run gen_test_pcap.py first")
	}

	// 1. Frames page (paginated)
	t.Run("page", func(t *testing.T) {
		result, err := runEpanCLIJSON("frames", "page", "--file", testPCAP, "--page", "1", "--size", "10")
		if err != nil {
			t.Fatal(err)
		}
		list, ok := result["list"].([]any)
		if !ok {
			t.Fatalf("frames page list not found: %v", result)
		}
		if len(list) != 10 {
			t.Errorf("page 1 size 10: got %d frames, want 10", len(list))
		}
		t.Logf("page 1: %d frames", len(list))
	})

	// 2. Frames page second page
	t.Run("page2", func(t *testing.T) {
		result, err := runEpanCLIJSON("frames", "page", "--file", testPCAP, "--page", "2", "--size", "10")
		if err != nil {
			t.Fatal(err)
		}
		list, ok := result["list"].([]any)
		if !ok {
			t.Fatalf("frames page list not found: %v", result)
		}
		if len(list) != 10 {
			t.Errorf("page 2 size 10: got %d frames, want 10", len(list))
		}
		t.Logf("page 2: %d frames", len(list))
	})

	// 3. Frames page with filter
	t.Run("page_filtered", func(t *testing.T) {
		result, err := runEpanCLIJSON("frames", "page", "--file", testPCAP, "--filter", "tcp", "--page", "1", "--size", "5")
		if err != nil {
			t.Fatal(err)
		}
		list, ok := result["list"].([]any)
		if !ok {
			t.Fatalf("frames page filtered list not found: %v", result)
		}
		if len(list) == 0 {
			t.Error("expected some TCP frames")
		}
		t.Logf("filtered page: %d frames", len(list))
	})

	// 4. Get frame by number
	t.Run("get_frame", func(t *testing.T) {
		result, err := runEpanCLIJSON("frames", "get", "--file", testPCAP, "--index", "1")
		if err != nil {
			t.Fatal(err)
		}
		layers, ok := result["layers"].(map[string]any)
		if !ok {
			t.Fatalf("layers not found in get_frame output: %v", result)
		}
		frame, ok := layers["frame"].(map[string]any)
		if !ok {
			t.Fatalf("frame layer not found: %v", layers)
		}
		if _, ok := frame["frame.number"]; !ok {
			t.Error("frame missing 'frame.number' field")
		}
		t.Logf("frame 1 number: %v", frame["frame.number"])
	})

	// 5. Get frame hex
	t.Run("hex", func(t *testing.T) {
		out, err := runEpanCLI("frames", "hex", "--file", testPCAP, "--index", "1")
		if err != nil {
			t.Fatal(err)
		}
		if out == "" {
			t.Error("hex output should not be empty")
		}
		t.Logf("hex frame 1: %d chars", len(out))
	})

	// 6. Batch frames
	t.Run("batch", func(t *testing.T) {
		result, err := runEpanCLIJSON("frames", "batch", "--file", testPCAP, "--indices", "1,5,10")
		if err != nil {
			t.Fatal(err)
		}
		list, ok := result["list"].([]any)
		if !ok {
			t.Fatalf("batch list not found: %v", result)
		}
		if len(list) != 3 {
			t.Errorf("batch got %d frames, want 3", len(list))
		}
		t.Logf("batch: %d frames", len(list))
	})

	// 7. Frame fields extraction (JSONL output)
	t.Run("fields", func(t *testing.T) {
		out, err := runEpanCLI("frames", "fields", "--file", testPCAP, "--fields", "frame.number,ip.src,ip.dst")
		if err != nil {
			t.Fatal(err)
		}
		lines := strings.Split(strings.TrimSpace(out), "\n")
		if len(lines) == 0 {
			t.Error("fields extraction should return data")
		}
		t.Logf("fields: %d rows", len(lines))
		// Parse first line as JSON
		var firstRow map[string]any
		if err := json.Unmarshal([]byte(lines[0]), &firstRow); err != nil {
			t.Fatalf("first line not valid JSON: %v", err)
		}
		for k, v := range firstRow {
			t.Logf("  field %s: %v", k, v)
		}
	})
}

