func TestIntegration_Filter(t *testing.T) {
	t.Run("validate", func(t *testing.T) {
		result, err := runEpanCLIJSON("filter", "validate", "--expr", "tcp.port == 80")
		if err != nil {
			t.Fatal(err)
		}
		valid, ok := result["valid"].(bool)
		if !ok {
			t.Fatalf("valid field not found: %v", result)
		}
		if !valid {
			t.Error("tcp.port == 80 should be valid")
		}
		t.Logf("filter valid: %v", valid)
	})

	t.Run("validate_invalid", func(t *testing.T) {
		result, err := runEpanCLIJSON("filter", "validate", "--expr", "invalid.field == 1")
		if err != nil {
			t.Fatal(err)
		}
		valid, ok := result["valid"].(bool)
		if !ok {
			t.Fatalf("valid field not found: %v", result)
		}
		if valid {
			t.Error("invalid.field should be invalid")
		}
		t.Logf("filter valid: %v", valid)
	})

	t.Run("validate_detailed", func(t *testing.T) {
		result, err := runEpanCLIJSON("filter", "validate-detailed", "--expr", "tcp.port == 80")
		if err != nil {
			t.Fatal(err)
		}
		t.Logf("validate-detailed: %v", result)
	})

	t.Run("suggest", func(t *testing.T) {
		result, err := runEpanCLIJSON("filter", "suggest", "--prefix", "tcp.", "--limit", "10")
		if err != nil {
			t.Fatal(err)
		}
		list, ok := result["fields"].([]any)
		if !ok {
			t.Fatalf("fields not found in suggest: %v", result)
		}
		if len(list) == 0 {
			t.Error("tcp. should have suggestions")
		}
		t.Logf("suggestions for 'tcp.': %d", len(list))
	})
}

