func TestIntegration_Slice(t *testing.T) {
	if testPCAP == "" {
		t.Skip("test pcap not found, run gen_test_pcap.py first")
	}

	outFile := filepath.Join(t.TempDir(), "slice.pcap")

	t.Run("slice_by_filter", func(t *testing.T) {
		result, err := runEpanCLIJSON("slice", "pcap", "--file", testPCAP, "--filter", "frame.number <= 10", "--out", outFile)
		if err != nil {
			t.Fatal(err)
		}
		t.Logf("slice result: %v", result)

		// Verify the output file exists
		if _, err := os.Stat(outFile); os.IsNotExist(err) {
			t.Error("slice output file not created")
		} else {
			t.Logf("slice output: %s exists", outFile)
		}
	})

	t.Run("slice_by_indices", func(t *testing.T) {
		outFile2 := filepath.Join(t.TempDir(), "slice2.pcap")
		result, err := runEpanCLIJSON("slice", "pcap", "--file", testPCAP, "--indices", "1,3,5,7", "--out", outFile2)
		if err != nil {
			t.Fatal(err)
		}
		t.Logf("slice by indices: %v", result)
		if _, err := os.Stat(outFile2); os.IsNotExist(err) {
			t.Error("slice by indices output file not created")
		}
	})
}

